SELECT ST_Area_Spheroid(
         ST_ConvexHull(
           ST_Collect([
             (SELECT geometry FROM br_sp_municipalities WHERE NM_MUN = 'Guarulhos'),
             (SELECT geometry FROM br_sp_municipalities WHERE NM_MUN = 'Praia Grande'),
             (SELECT geometry FROM br_sp_municipalities WHERE NM_MUN = 'Salto de Pirapora')
           ])
         )::GEOMETRY
       ) / 1000000.0 AS convex_hull_area_km2

