WITH buf AS (
  SELECT ST_Transform(
           ST_Buffer(
             ST_Transform(ST_Point(4.754, 52.9226), 'EPSG:4326', 'EPSG:32631', always_xy := true),
             10000
           ),
           'EPSG:32631', 'EPSG:4326', always_xy := true
         ) AS geom
)
SELECT count(*) AS n_municipalities, sum(oppervlakte_land_in_ha) AS total_land_ha
FROM nl_municipalities, buf
WHERE water = 'NEE' AND ST_Intersects(geometry, buf.geom);

