WITH e AS (
  SELECT ST_Envelope(ST_Collect(list(geometry))) AS geom
  FROM tokyo_places
)
SELECT ST_Area_Spheroid(geom) / 1000000 AS area_km2
FROM e;

WITH pt AS (
  SELECT ST_Transform(ST_Point(28.283, -15.417), 'EPSG:4326', 'EPSG:32735', always_xy := true) AS geom
),
buffer AS (
  SELECT ST_Buffer(geom, 50000) AS geom FROM pt
),
buffer_wgs AS (
  SELECT ST_Transform(geom, 'EPSG:32735', 'EPSG:4326', always_xy := true) AS geom FROM buffer
)
SELECT COUNT(*) AS num_hospitals
FROM zm_health_facilities h, buffer_wgs b
WHERE h.NAME2_ = 'District Hospital'
  AND ST_Intersects(h.geometry, b.geom);

WITH buffered AS (
  SELECT ST_Buffer(ST_Transform(geometry, 'EPSG:4326', 'EPSG:32735', always_xy := true), 10000) AS geom
  FROM zm_health_facilities
  WHERE NAME2_ = 'Mission Hospital'
),
unioned AS (
  SELECT ST_Union_Agg(geom) AS geom FROM buffered
)
SELECT ST_Area(geom) / 1e6 AS area_km2
FROM unioned;
